<?php

namespace Database\Seeders;

/** Seeds `seasons` from database/seeders/data/seasons.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class SeasonsSeeder extends ContentSeederBase
{
    public const TABLE = 'seasons';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        // If `seasons` has no slug column yet, rows are matched by name_ar (see 03-seeders.md: add `slug`).
        $images = [];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('seasons') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
